#!/bin/bash
# ==============================================================================
# GKE Cleanup Utility
# Cleans up JobSets, ConfigMaps, and Helm releases generated by benchmark runs.
# ==============================================================================

set -euo pipefail

CURRENT_USER=$(whoami | sed 's/[^a-zA-Z0-9]/-/g' | tr '[:upper:]' '[:lower:]')
CLEAN_USER="${CURRENT_USER:0:10}"

usage() {
    echo "Usage:"
    echo "  $0 <JOB_OR_RELEASE_NAME>    Clean up a specific JobSet and its ConfigMap"
    echo "  $0 --all                    Clean up ALL JobSets and ConfigMaps belonging to user '${CLEAN_USER}'"
    echo "  $0 --configmaps             Clean up ALL orphaned ConfigMaps matching '${CLEAN_USER}-test-*-scripts'"
    echo "  $0 -h | --help              Show this help message"
    echo ""
    echo "Examples:"
    echo "  $0 my-benchmark-job"
    echo "  $0 --all"
    echo "  $0 --configmaps"
    exit 1
}

if [ $# -lt 1 ]; then
    usage
fi

TARGET="$1"

case "$TARGET" in
    -h|--help)
        usage
        ;;
    --configmaps)
        echo "🧹 Finding and deleting all orphaned ConfigMaps for user '${CLEAN_USER}'..."
        CMS=$(kubectl get configmap -o name 2>/dev/null | grep "configmap/${CLEAN_USER}-test-" | grep -- "-scripts" || true)
        if [ -n "$CMS" ]; then
            echo "$CMS" | xargs -r kubectl delete
            echo "✅ Orphaned ConfigMaps cleaned up successfully."
        else
            echo "ℹ️ No orphaned ConfigMaps found for user '${CLEAN_USER}'."
        fi
        ;;
    --all)
        echo "⚠️ Cleaning up ALL JobSets and ConfigMaps for user '${CLEAN_USER}'..."
        JOBSETS=$(kubectl get jobset -o name 2>/dev/null | grep "jobset.jobset.x-k8s.io/${CLEAN_USER}-test-" || true)
        if [ -n "$JOBSETS" ]; then
            echo "$JOBSETS" | xargs -r kubectl delete
            echo "✅ JobSets deleted."
        else
            echo "ℹ️ No active JobSets found for user '${CLEAN_USER}'."
        fi

        CMS=$(kubectl get configmap -o name 2>/dev/null | grep "configmap/${CLEAN_USER}-test-" | grep -- "-scripts" || true)
        if [ -n "$CMS" ]; then
            echo "$CMS" | xargs -r kubectl delete
            echo "✅ ConfigMaps deleted."
        else
            echo "ℹ️ No ConfigMaps found for user '${CLEAN_USER}'."
        fi
        ;;
    *)
        JOB_NAME="$TARGET"
        echo "🧹 Cleaning up resources for '${JOB_NAME}'..."

        # Check if Helm release
        if command -v helm &>/dev/null && helm status "$JOB_NAME" &>/dev/null; then
            echo "Uninstalling Helm release '${JOB_NAME}'..."
            helm uninstall "$JOB_NAME" || true
        fi

        # Delete JobSet
        if kubectl get jobset "$JOB_NAME" &>/dev/null; then
            echo "Deleting JobSet '${JOB_NAME}'..."
            kubectl delete jobset "$JOB_NAME" || true
        fi

        # Delete ConfigMap
        if kubectl get configmap "${JOB_NAME}-scripts" &>/dev/null; then
            echo "Deleting ConfigMap '${JOB_NAME}-scripts'..."
            kubectl delete configmap "${JOB_NAME}-scripts" || true
        fi

        echo "✅ Cleanup completed for '${JOB_NAME}'."
        ;;
esac
